"""Durable-state verification for the Android Delta Chat tasks.

These tasks leave two kinds of record behind.  Delta Chat's own database holds
the conversations the workflow created or wrote into, with their names,
descriptions and messages.  The note editor holds the note files the workflow
wrote, with their exact content.

A judgement reads both and compares them against the outcome the instruction
asks for.  Each task states that outcome beside its evaluator -- the texts the
instruction names verbatim -- which keeps every criterion traceable to the step
that asks for it.

Only what persists is compared.  Which screen a text was typed on, how the
conversation was reached, and in which order attachments were picked leave no
durable trace and are not judged.
"""

from __future__ import annotations

from typing import Any, Mapping, Sequence

from evaluators.cua_review.core.evaluation import BaseEvaluator, EvalResult, EvalStatus
from evaluators.cua_review.platforms.android.deltachat_store import (
    DEFAULT_APP_PACKAGE,
    DEFAULT_MARKOR_PACKAGE,
    DeltaChatAndroidStore,
    MarkorNote,
    normalize,
)


def check(name: str, passed: bool, expected: Any, observed: Any) -> dict[str, Any]:
    """Build one check record."""
    return {
        "name": name,
        "passed": bool(passed),
        "expected": expected,
        "observed": observed,
        "failure_reason": None if passed else "durable value or cardinality mismatch",
    }


class DeltaChatAndroidEvaluator(BaseEvaluator):
    """Verify the conversations and note files a Delta Chat task left behind.

    Subclasses state the outcome their instruction asks for: the conversation
    the task creates, so that its name, description and messages can be
    compared, and the note file the task writes, so that its content can be
    compared.  Everything else -- which screen a text was typed on, how a
    conversation was reached, in which order attachments were picked -- leaves
    no durable trace and is not judged.
    """

    #: Conversation the task creates: ``name``, ``description`` and ``messages``.
    EXPECTED_GROUP: Mapping[str, Any] = {}

    #: Note file the task writes: ``title`` and the ``lines`` it must contain.
    EXPECTED_NOTE: Mapping[str, Any] = {}

    #: Identifier the task binds to this evaluator.
    TASK_ID = ""

    #: Identifier this evaluator is registered under.
    EVALUATOR_ID = ""

    @classmethod
    def expected_outcome(cls) -> dict[str, Any]:
        """Return the outcome this evaluator requires."""
        return {
            "group_name": str(cls.EXPECTED_GROUP.get("name") or ""),
            "group_description": str(cls.EXPECTED_GROUP.get("description") or ""),
            "messages": list(cls.EXPECTED_GROUP.get("messages") or []),
            "note_title": str(cls.EXPECTED_NOTE.get("title") or ""),
            "note_lines": list(cls.EXPECTED_NOTE.get("lines") or []),
            "require_archived": bool(cls.EXPECTED_GROUP.get("archived")),
        }

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        params = dict(context.get("params") or {})
        if controller is None or not hasattr(controller, "execute_adb"):
            return EvalResult(
                status=EvalStatus.ERROR,
                message="runner-provided controller.execute_adb is required",
                metadata={"read_only": True},
            )

        expected = self.expected_outcome()
        expected.update(
            {
                key: value
                for key, value in params.items()
                if key in ("group_name", "group_description", "messages",
                           "note_title", "note_lines", "require_archived")
            }
        )
        if not (expected.get("group_name") or expected.get("note_title")):
            return EvalResult(
                status=EvalStatus.ERROR,
                message="this evaluator states no conversation and no note to verify",
                metadata={"read_only": True},
            )

        store = DeltaChatAndroidStore(
            controller,
            app_package=str(params.get("app_package") or DEFAULT_APP_PACKAGE),
            markor_package=str(params.get("markor_package") or DEFAULT_MARKOR_PACKAGE),
            markor_dirs=params.get("markor_dirs") or None,
        )

        try:
            chats = store.read_chats()
            messages = store.read_chat_messages()
            notes = store.read_notes()
        except Exception as exc:  # noqa: BLE001
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"Failed to read Delta Chat state: {type(exc).__name__}: {exc}",
                metadata={
                    "read_only": True,
                    "app_package": store.app_package,
                    "exception_type": type(exc).__name__,
                },
            )

        checks: list[dict[str, Any]] = []
        group_name = str(expected.get("group_name") or "")

        if group_name:
            matches = [chat for chat in chats if normalize(chat.get("name")) == group_name]
            chat = matches[0] if len(matches) == 1 else {}
            checks.append(
                check(
                    "group_conversation_unique",
                    len(matches) == 1,
                    {"name": group_name, "match_count": 1},
                    {
                        "match_count": len(matches),
                        "ids": [item.get("id") for item in matches],
                    },
                )
            )
            description = str(expected.get("group_description") or "")
            if description:
                chat_messages = [
                    message
                    for message in messages
                    if str(message.get("chat_id")) == str(chat.get("id"))
                ]
                checks.append(
                    check(
                        "group_description_exact",
                        _description_matches(chat, chat_messages, description),
                        description,
                        {
                            "chat_name": chat.get("name"),
                            "message_texts": [item.get("text") for item in chat_messages][:5],
                        },
                    )
                )
            group_messages = [
                message
                for message in messages
                if str(message.get("chat_id")) == str(chat.get("id"))
                and message.get("outgoing")
            ]
            for text in expected.get("messages") or []:
                present = [item for item in group_messages if str(item.get("text") or "").strip() == text]
                checks.append(
                    check(
                        f"message_{text}",
                        bool(present),
                        {"text": text},
                        {
                            "match_count": len(present),
                            "ids": [item.get("id") for item in present][:5],
                        },
                    )
                )
            if expected.get("require_archived"):
                checks.append(
                    check(
                        "group_archived",
                        _is_archived(chat.get("archived")),
                        True,
                        chat.get("archived"),
                    )
                )

        note_title = str(expected.get("note_title") or "")
        if note_title:
            found = store.find_note(note_title) if notes is not None else []
            if not found:
                found = [
                    note
                    for note in notes
                    if normalize(note.path.rsplit("/", 1)[-1].rsplit(".", 1)[0]) == normalize(note_title)
                ]
            checks.append(
                check(
                    "note_file_unique",
                    len(found) == 1,
                    {"title": note_title, "match_count": 1},
                    {
                        "match_count": len(found),
                        "paths": [note.path for note in found],
                    },
                )
            )
            note: MarkorNote | None = found[0] if len(found) == 1 else None
            lines = expected.get("note_lines") or []
            if note is not None and lines:
                body = note.text
                missing = [line for line in lines if line not in body]
                checks.append(
                    check(
                        "note_lines_present_in_order",
                        not missing and _in_order(body, lines),
                        {"line_count": len(lines)},
                        {
                            "missing": missing[:10],
                            "observed_lines": body.splitlines()[:15],
                        },
                    )
                )

        failures = [entry["name"] for entry in checks if not entry["passed"]]
        metadata = {
            "read_only": True,
            "app_package": store.app_package,
            "checks": checks,
            "failures": failures,
            "expected_outcome": expected,
            "chat_count": len(chats),
            "message_count": len(messages),
            "note_count": len(notes),
        }
        if failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Delta Chat durable state does not match the requested outcome",
                metadata=metadata,
            )
        return EvalResult(
            status=EvalStatus.PASS,
            message="Delta Chat durable state matches the requested outcome",
            metadata=metadata,
        )


def _is_archived(value: Any) -> bool:
    """Whether a stored archival flag means the conversation is archived.

    The flag is stored as a number in the application's database, so both the
    numeric and the boolean spellings are recognized.
    """
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return int(value) == 1
    return str(value or "").strip().lower() in ("1", "true")


def _description_matches(
    chat: Mapping[str, Any], messages: Sequence[Mapping[str, Any]], description: str
) -> bool:
    """Whether a conversation records the description the task asked for.

    A description is stored with the conversation in some builds and delivered
    as the conversation's first message in others; both carry the same text, so
    both are accepted.
    """
    if normalize(chat.get("description")) == description:
        return True
    return any(
        normalize(message.get("text")) == description for message in messages
    )


def _in_order(body: str, lines: Sequence[str]) -> bool:
    """Whether every line appears in *body* in the order given."""
    position = 0
    for line in lines:
        index = body.find(line, position)
        if index < 0:
            return False
        position = index + len(line)
    return True


